import{_ as o,C as r,o as s,c as i,a2 as a,b as l,w as t,a as p,E as d,a3 as c}from"./chunks/framework.BC3NdntU.js";const C=JSON.parse('{"title":"2.3 渲染管线详解","description":"","frontmatter":{},"headers":[],"relativePath":"卷二-浏览器工作原理/2.3-渲染管线详解.md","filePath":"卷二-浏览器工作原理/2.3-渲染管线详解.md","lastUpdated":1788840986000}'),h={name:"卷二-浏览器工作原理/2.3-渲染管线详解.md"};function u(g,e,m,b,E,q){const n=r("Mermaid");return s(),i("div",null,[e[1]||(e[1]=a('<h1 id="_2-3-渲染管线详解" tabindex="-1">2.3 渲染管线详解 <a class="header-anchor" href="#_2-3-渲染管线详解" aria-label="Permalink to &quot;2.3 渲染管线详解&quot;">​</a></h1><blockquote><p>卷:卷二 · 浏览器工作原理 阅读时间:30min</p></blockquote><hr><h2 id="引言-从两棵树到屏幕像素的流水线" tabindex="-1">引言:从两棵树到屏幕像素的流水线 <a class="header-anchor" href="#引言-从两棵树到屏幕像素的流水线" aria-label="Permalink to &quot;引言:从两棵树到屏幕像素的流水线&quot;">​</a></h2><p>渲染主流程不复杂,但每段都有易误解的细节。本章把每一段拆透,重点讲清「布局树≠DOM 树」「分层」「绘制≠像素」,并补三个深层细节:样式计算的来源、绘制的&quot;指令&quot;具体是什么、合成的&quot;帧&quot;怎么提交。</p><hr><h2 id="一、渲染管线六段-总览" tabindex="-1">一、渲染管线六段(总览) <a class="header-anchor" href="#一、渲染管线六段-总览" aria-label="Permalink to &quot;一、渲染管线六段(总览)&quot;">​</a></h2>',7)),(s(),l(c,null,{default:t(()=>[d(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BHTML%5D%20--%3E%20B%5BDOM%20%E6%A0%91%5D%0A%20%20%20%20C%5BCSS%5D%20--%3E%20D%5BCSSOM%20%E6%A0%91%5D%0A%20%20%20%20B%20--%3E%20E%5B%E6%A0%B7%E5%BC%8F%E8%AE%A1%E7%AE%97%20computed%20style%5D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%20F%5B%E5%B8%83%E5%B1%80%E6%A0%91%20Layout%20Tree%5D%0A%20%20%20%20F%20--%3E%20G%5B%E5%88%86%E5%B1%82%20Layer%20Tree%5D%0A%20%20%20%20G%20--%3E%20H%5B%E7%BB%98%E5%88%B6%20Paint%20%E6%8C%87%E4%BB%A4%5D%0A%20%20%20%20H%20--%3E%20I%5B%E5%88%86%E5%9D%97%20%2B%20%E5%85%89%E6%A0%85%E5%8C%96%20Raster%20%E4%BD%8D%E5%9B%BE%5D%0A%20%20%20%20I%20--%3E%20J%5B%E5%90%88%E6%88%90%20Composite%20%E6%8F%90%E4%BA%A4%20GPU%20%E2%86%92%20%E6%98%BE%E7%A4%BA%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<hr><h2 id="二、1-dom-树-2-cssom-树" tabindex="-1">二、① DOM 树 &amp; ② CSSOM 树 <a class="header-anchor" href="#二、1-dom-树-2-cssom-树" aria-label="Permalink to &quot;二、① DOM 树 &amp; ② CSSOM 树&quot;">​</a></h2><ul><li>DOM:解析 HTML 得到(结构);CSSOM:解析 CSS 得到(样式规则)</li><li>两者缺一不可:CSSOM 没就绪渲染得等(&quot;CSS 阻塞渲染&quot;根源,2.2)</li></ul><p><strong>关键渲染路径(Critical Rendering Path, CRP):</strong></p><p>首屏渲染的完整依赖链:<strong>HTML→DOM,CSS→CSSOM,DOM+CSSOM→渲染树→布局→绘制→合成</strong>。CRP 优化的核心是<strong>缩短这条链</strong>:</p><ul><li><strong>减少阻塞</strong>:CSS 尽早就绪、JS 用 <code>async</code>/<code>defer</code>(2.2)</li><li><strong>减少关键资源</strong>:内联关键 CSS、延迟非关键 CSS/JS</li><li><strong>减少往返</strong>:关键资源走 HTTP/2 多路复用、CDN(4.3/4.4)</li></ul><blockquote><p>为什么叫&quot;关键&quot;?因为<strong>只有这条链上的资源会影响首屏时间</strong>——非关键资源(图片、非首屏 JS)不该阻塞它。这是性能优化里&quot;加载&quot;与&quot;渲染&quot;的桥(呼应 10.2/10.3)。</p></blockquote><hr><h2 id="三、3-样式计算-computed-style-布局树" tabindex="-1">三、③ 样式计算(computed style)+ 布局树 <a class="header-anchor" href="#三、3-样式计算-computed-style-布局树" aria-label="Permalink to &quot;三、③ 样式计算(computed style)+ 布局树&quot;">​</a></h2><p><strong>样式计算</strong>:把 DOM 每个节点 + 所有匹配 CSS + 继承 + 默认值,合并成最终样式——就是卷三 3.5 的「属性计算过程」。DevTools 的 &quot;Computed&quot; 面板即产物。</p><p><strong>布局树(Layout Tree)三误区:</strong></p><blockquote><ul><li><code>display:none</code> <strong>不在布局树</strong>;<code>::before/::after</code> <strong>在</strong>(DOM 里没有);<code>&lt;head&gt;</code>/<code>&lt;script&gt;</code> 不在</li><li>布局树带<strong>几何信息</strong>(位置/尺寸)——这是&quot;布局(layout)&quot;的产物</li></ul></blockquote><hr><h2 id="四、4-分层-layer-tree" tabindex="-1">四、④ 分层(Layer Tree) <a class="header-anchor" href="#四、4-分层-layer-tree" aria-label="Permalink to &quot;四、④ 分层(Layer Tree)&quot;">​</a></h2><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: translateZ(0);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 3D 变换 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">will-change</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: transform, opacity;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: blur(5px);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">position: fixed / sticky;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">canvas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / iframe;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>为什么分层(深层)?</strong> 把&quot;高频变化的部分&quot;独立成层,实现<strong>独立重绘 + GPU 合成</strong>:动画在专属层跑不影响其他层;滚动直接移图层位图。这是&quot;用内存换渲染效率&quot;的权衡——所以有 2.5 的&quot;层爆炸&quot;风险。</p><hr><h2 id="五、5-绘制-paint-指令不是像素" tabindex="-1">五、⑤ 绘制(Paint):指令不是像素 <a class="header-anchor" href="#五、5-绘制-paint-指令不是像素" aria-label="Permalink to &quot;五、⑤ 绘制(Paint):指令不是像素&quot;">​</a></h2><p>绘制的产物是<strong>绘制指令(draw commands)</strong>:画矩形、画文字、画圆角……按图层与 Z 序记录。这一步仍在<strong>渲染主线程</strong>。</p><p><strong>深层:指令具体长什么样?</strong> 本质是告诉合成线程&quot;<strong>在哪个图层、按什么顺序、画什么</strong>&quot;的几何描述(类似 Canvas 的 <code>moveTo/lineTo/fill</code> 那套 draw operations)。到这一步,主线程工作完成,移交合成线程。</p><hr><h2 id="六、6-光栅化-合成-交给合成线程-gpu" tabindex="-1">六、⑥ 光栅化 + 合成(交给合成线程/GPU) <a class="header-anchor" href="#六、6-光栅化-合成-交给合成线程-gpu" aria-label="Permalink to &quot;六、⑥ 光栅化 + 合成(交给合成线程/GPU)&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>合成线程 → 分块 Tiling → 多线程光栅化(指令→位图)→ 计算层级/滚动偏移 → 合成 Compositor Frame → 提交 GPU</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>深层:合成产出的是&quot;Compositor Frame&quot;</strong>——一个描述&quot;各图层位图如何叠加、位置与区域如何&quot;的数据结构,交给 GPU 进程最终上屏。滚动的本质就是<strong>合成线程直接复用已光栅化位图、只改滚动偏移、重发一帧</strong>,不动主线程。</p><p><strong>为什么&quot;绘制&quot;和&quot;光栅化&quot;要分开?</strong> 绘制是<strong>逻辑</strong>(主线程,画什么);光栅化是<strong>算力</strong>(合成线程/GPU,转像素)。解耦换来:① 像素生成不占主线程;② 可<strong>按视口分块、优先光栅化可见区</strong>,滚到哪补哪。</p><hr><h2 id="七、小结" tabindex="-1">七、小结 <a class="header-anchor" href="#七、小结" aria-label="Permalink to &quot;七、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTML→DOM + CSS→CSSOM →样式计算→布局树(仅可见+几何)→分层→绘制(指令)</span></span>
<span class="line"><span>→分块→光栅化(位图)→合成(Compositor Frame)→GPU 显示</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三误区:布局树≠DOM;分层为性能;绘制≠像素</span></span>
<span class="line"><span>深层:绘制=draw commands;合成=Compositor Frame;滚动=合成线程改偏移重发帧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="八、面试题" tabindex="-1">八、面试题 <a class="header-anchor" href="#八、面试题" aria-label="Permalink to &quot;八、面试题&quot;">​</a></h2><p><strong>Q1:<code>display:none</code>、<code>visibility:hidden</code>、<code>opacity:0</code> 谁在布局树?</strong></p><p><code>display:none</code> <strong>不在</strong>(不占位不渲染);<code>visibility:hidden</code> <strong>在</strong>(占位不可见);<code>opacity:0</code> <strong>在</strong>(占位,合成层处理,通常不触发 layout)。</p><p><strong>Q2:为什么说&quot;绘制&quot;和&quot;光栅化&quot;是两回事?</strong></p><p>绘制在主线程<strong>生成绘制指令</strong>(画什么、按什么顺序);光栅化在合成线程把指令<strong>转成位图像素</strong>。一个重逻辑、一个重计算,分离才能并行加速。</p><p><strong>Q3:如果动画只改 <code>opacity</code>,管线的哪一步会执行?</strong></p><p>只走<strong>合成阶段</strong>:布局、绘制都不重来,直接调图层透明度并合成,全程合成线程/GPU,主线程零参与——这是 transform/opacity 流畅的根本(2.5)。</p><p><strong>Q4:简述&quot;滚动&quot;在渲染管线里是如何高效实现的?</strong></p><p>滚动<strong>不触发布局</strong>:合成线程直接<strong>复用已光栅化位图、只改变滚动偏移、重发一帧 Compositor Frame</strong>。因为没布局变动,所以滚动在很多场景下主线程几乎无感。</p><p><strong>Q5:为什么把元素&quot;提升为合成层&quot;能加速动画,但也可能变慢?</strong></p><p>加速:动画只在独立层 + 合成线程跑,不动布局/不打扰其他层。变慢(层爆炸):层太多 → 位图内存暴涨、光栅化开销增加,甚至隐式提升雪球。所以只在真正的动画元素上用。</p><p><strong>Q6:从管线角度,为什么&quot;首屏快&quot;要减少 JS 阻塞 + CSS 尽早就绪?</strong></p><p>JS 阻塞 → DOM 树构建推迟(DOMContentLoaded 延后);CSS 未就绪 → 样式计算/渲染等 CSSOM 全卡。两者都会推迟&quot;布局树→绘制→合成&quot;这条链的启动,首屏随之变慢。</p><hr><p>📎 参考:Google Web Fundamentals《渲染性能》、Chrome Developers《Inside look》渲染篇、chromium Compositor 文档</p><p>📎 权威延伸阅读:</p><ul><li>《Critical rendering path》(web.dev) <a href="https://web.dev/articles/critical-rendering-path" target="_blank" rel="noreferrer">https://web.dev/articles/critical-rendering-path</a></li><li>《Rendering performance / The pixel pipeline》(web.dev) <a href="https://web.dev/articles/rendering-performance" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-performance</a></li><li>《Inside look》(Part 3: Inner workings of a renderer)(Chrome Developers) <a href="https://developer.chrome.com/blog/inside-browser-part3/" target="_blank" rel="noreferrer">https://developer.chrome.com/blog/inside-browser-part3/</a></li></ul>`,46))])}const S=o(h,[["render",u]]);export{C as __pageData,S as default};
